            int n;
            while ((n = reader.read(buffer)) != -1) {
                if (n < 10) {
                    buffer = Arrays.copyOf(buffer, n);
                }
                stringBuilder.append(String.valueOf(buffer));
                buffer = new char[10];
            }
        } catch (IOException e) {
            logger.error(COMMON_IO_EXCEPTION, "", "", "Read migration file error.", e);
        }

        return stringBuilder.toString();
    }

